-- Code generated by postgres/lease/ownership/cmd/bundle; DO NOT EDIT.
-- Shared ownership of module-owned rows. No resource/work rows live here.
CREATE SCHEMA IF NOT EXISTS dbtx;

-- Accept the lease columns directly or the retry facade's existing aliases.
CREATE OR REPLACE FUNCTION dbtx.ownership_column(p_table regclass, p_name text, p_alias text)
RETURNS text LANGUAGE plpgsql STABLE AS $$
DECLARE v_name text;
BEGIN
    SELECT quote_ident(attname) INTO v_name FROM pg_attribute
     WHERE attrelid=p_table AND attname=ANY(ARRAY[p_name,p_alias]) AND attnum>0 AND NOT attisdropped
     ORDER BY (attname=p_name) DESC LIMIT 1;
    IF v_name IS NULL THEN
        RAISE EXCEPTION 'ownership: % lacks %/%',p_table,p_name,p_alias USING ERRCODE='22023';
    END IF;
    RETURN v_name;
END;
$$;

-- Native key comparisons preserve the base table's index, including composite
-- (namespace, key) resource indexes exposed as (namespace, id) by a view.
CREATE OR REPLACE FUNCTION dbtx.ownership_key(p_table regclass, p_namespace text)
RETURNS text LANGUAGE plpgsql STABLE AS $$
DECLARE v_type text; v_id text;
BEGIN
    SELECT quote_ident(attname),format_type(atttypid,atttypmod) INTO v_id,v_type FROM pg_attribute
     WHERE attrelid=p_table AND attname=ANY(ARRAY['id','retry_key']) AND attnum>0 AND NOT attisdropped
     ORDER BY (attname='id') DESC LIMIT 1;
    IF v_type IS NULL THEN
        RAISE EXCEPTION 'ownership: % has no id column', p_table USING ERRCODE = '22023';
    END IF;
    RETURN format('%s = $1::%s%s', v_id,v_type,
        CASE WHEN p_namespace IS NULL THEN '' ELSE ' AND namespace = $2' END);
END;
$$;

-- Read raw values before evaluating expiry. An expression in the SELECT list
-- can be evaluated before FOR UPDATE waits; the caller checks the clock AFTER
-- this function has acquired the row lock. The lock lasts until transaction end.
CREATE OR REPLACE FUNCTION dbtx.ownership_row(
    p_table regclass, p_id text, p_namespace text, p_status boolean, p_nowait boolean
) RETURNS TABLE(owner_id text, token bigint, lease_expires_at timestamptz, status text)
LANGUAGE plpgsql VOLATILE AS $$
BEGIN
    RETURN QUERY EXECUTE format('SELECT %s, %s, lease_expires_at, %s
        FROM %s WHERE %s FOR UPDATE %s',
        dbtx.ownership_column(p_table,'owner_id','lease_owner'), dbtx.ownership_column(p_table,'token','fencing_token'),
        CASE WHEN p_status THEN 'status::text' ELSE 'NULL::text' END,
        p_table, dbtx.ownership_key(p_table, p_namespace),
        CASE WHEN p_nowait THEN 'NOWAIT' ELSE '' END)
    USING p_id, p_namespace;
END;
$$;

CREATE OR REPLACE FUNCTION dbtx.ownership_lock(
    p_table regclass, p_id text, p_namespace text, p_owner text, p_token bigint,
    p_status text, p_require_unexpired boolean, p_check_owner boolean, p_check_token boolean
) RETURNS boolean LANGUAGE plpgsql VOLATILE AS $$
DECLARE v record;
BEGIN
    SELECT * INTO v FROM dbtx.ownership_row(p_table, p_id, p_namespace, p_status IS NOT NULL, false);
    IF NOT FOUND THEN RETURN false; END IF;
    RETURN (NOT p_check_owner OR (p_owner IS NOT NULL AND v.owner_id IS NOT DISTINCT FROM p_owner))
       AND (NOT p_check_token OR (p_token IS NOT NULL AND v.token IS NOT DISTINCT FROM p_token))
       AND (p_status IS NULL OR v.status IS NOT DISTINCT FROM p_status)
       AND (NOT p_require_unexpired OR coalesce(v.lease_expires_at > clock_timestamp(), false));
END;
$$;

-- The caller selects eligible work and/or initializes a persistent resource
-- row in this same transaction. Grant never changes domain status or attempts.
-- NULL sequence means a permanent per-key generation; a sequence preserves
-- token history for purgeable work. Unfenced messages retain their owner guard.
CREATE OR REPLACE FUNCTION dbtx.ownership_grant(
    p_table regclass, p_id text, p_namespace text, p_owner text, p_ttl interval,
    p_sequence regclass, p_fenced boolean, p_touch boolean, p_write_at timestamptz
) RETURNS bigint LANGUAGE plpgsql VOLATILE AS $$
DECLARE v record; v_token bigint; v_now timestamptz;
BEGIN
    SELECT * INTO v FROM dbtx.ownership_row(p_table, p_id, p_namespace, false, true);
    IF NOT FOUND THEN RETURN 0; END IF;
    v_now := clock_timestamp();
    IF v.owner_id IS NOT NULL AND v.lease_expires_at > v_now THEN RETURN 0; END IF;
    IF p_owner IS NULL OR p_ttl IS NULL THEN
        RAISE EXCEPTION 'ownership: grant needs owner and TTL' USING ERRCODE = '22023';
    END IF;
    IF NOT p_fenced THEN v_token := 1;
    ELSIF p_sequence IS NOT NULL THEN v_token := nextval(p_sequence);
    ELSE
        IF v.token = 9223372036854775807 THEN
            RAISE EXCEPTION 'lease fencing token exhausted' USING ERRCODE = '22003';
        END IF;
        v_token := v.token + 1;
    END IF;
    EXECUTE format('UPDATE %s SET %s = $3, lease_expires_at = $4 %s %s WHERE %s',
        p_table, dbtx.ownership_column(p_table,'owner_id','lease_owner'),
        CASE WHEN p_fenced THEN ', '||dbtx.ownership_column(p_table,'token','fencing_token')||' = $5' ELSE '' END,
        CASE WHEN p_touch THEN ', updated_at = $6' ELSE '' END,
        dbtx.ownership_key(p_table, p_namespace))
    USING p_id, p_namespace, p_owner, coalesce(p_write_at, v_now) + p_ttl, v_token,
          coalesce(p_write_at, v_now);
    RETURN v_token;
EXCEPTION WHEN lock_not_available THEN RETURN 0;
END;
$$;

CREATE OR REPLACE FUNCTION dbtx.ownership_renew(
    p_table regclass, p_id text, p_namespace text, p_owner text, p_token bigint,
    p_status text, p_require_unexpired boolean, p_check_owner boolean, p_check_token boolean,
    p_ttl interval, p_touch boolean, p_write_at timestamptz
) RETURNS boolean LANGUAGE plpgsql VOLATILE AS $$
DECLARE v_now timestamptz;
BEGIN
    IF NOT dbtx.ownership_lock(p_table, p_id, p_namespace, p_owner, p_token,
        p_status, p_require_unexpired, p_check_owner, p_check_token) THEN RETURN false; END IF;
    v_now := coalesce(p_write_at, clock_timestamp());
    EXECUTE format('UPDATE %s SET lease_expires_at = $3 %s WHERE %s',
        p_table, CASE WHEN p_touch THEN ', updated_at = $4' ELSE '' END,
        dbtx.ownership_key(p_table, p_namespace))
    USING p_id, p_namespace, v_now + p_ttl, v_now;
    RETURN true;
END;
$$;

-- Release is ownership-only. Rows whose constraints couple status and ownership
-- must instead clear ownership with their domain outcome in a single UPDATE,
-- after ownership_lock. p_expiry preserves NULL vs -infinity resource storage.
CREATE OR REPLACE FUNCTION dbtx.ownership_release(
    p_table regclass, p_id text, p_namespace text, p_owner text, p_token bigint,
    p_status text, p_require_unexpired boolean, p_check_owner boolean, p_check_token boolean,
    p_expiry timestamptz, p_touch boolean, p_write_at timestamptz
) RETURNS boolean LANGUAGE plpgsql VOLATILE AS $$
BEGIN
    IF NOT dbtx.ownership_lock(p_table, p_id, p_namespace, p_owner, p_token,
        p_status, p_require_unexpired, p_check_owner, p_check_token) THEN RETURN false; END IF;
    EXECUTE format('UPDATE %s SET %s = NULL, lease_expires_at = $3 %s WHERE %s',
        p_table, dbtx.ownership_column(p_table,'owner_id','lease_owner'), CASE WHEN p_touch THEN ', updated_at = $4' ELSE '' END,
        dbtx.ownership_key(p_table, p_namespace))
    USING p_id, p_namespace, p_expiry, coalesce(p_write_at, clock_timestamp());
    RETURN true;
END;
$$;
create schema if not exists dbtx;

-- Calculate before exponentiating, so large attempt counts cannot overflow.
create or replace function dbtx.retry_delay(p_attempts integer, p_base float8, p_cap float8)
returns float8 language sql immutable strict as $$
    select case
        when p_base <= 0 or p_cap <= 0 then 0::float8
        when p_base >= p_cap then p_cap
        else least(p_cap, p_base * power(2::float8, least(
            greatest(p_attempts - 1, 0),
            ceil(log(2::numeric, p_cap::numeric / p_base::numeric))::integer
        )::float8))
    end;
$$;

-- Canonical view columns:
-- retry_key (native primary-key type), status (native enum/text), attempts,
-- max_attempts, lease_owner, fencing_token, retry_at, lease_expires_at,
-- last_error, completed_at, updated_at. Original columns may also be exposed.
-- Synthetic max_attempts/fencing_token are permitted when they are not written.
-- retry_at and lease_expires_at may alias one legacy column; only idempotency
-- opts into separate_lease, which clears its independently stored expiry.
--
-- All identifiers come from regclass/catalogs, and all values are bound. This is
-- SECURITY INVOKER: callers need ordinary access to the view and underlying row.
-- No commits, independent transactions or external locks occur here.
create or replace function dbtx.retry_transition(
    p_relation regclass, p_key text, p_action text,
    p_owner text, p_token bigint, p_policy jsonb, p_options jsonb,
    p_now timestamptz
) returns setof jsonb language plpgsql volatile as $$
declare
    key_type text;
    status_type text;
    expected text[];
    state jsonb;
    result jsonb;
    next_status text;
    next_owner text;
    next_error text;
    next_attempts integer;
    max_attempts integer;
    terminal boolean;
    delay_seconds float8;
    next_at timestamptz;
    next_completed timestamptz;
    assignments text;
    projection text := 'jsonb_build_object(
        ''retry_key'', retry_key, ''status'', status, ''attempts'', attempts,
        ''max_attempts'', max_attempts, ''lease_owner'', lease_owner,
        ''fencing_token'', fencing_token, ''retry_at'', retry_at,
        ''lease_expires_at'', lease_expires_at, ''last_error'', last_error,
        ''completed_at'', completed_at, ''updated_at'', updated_at)';
begin
    if p_action not in ('claim', 'renew', 'nack', 'complete', 'fail', 'release', 'requeue', 'expire') then
        raise exception 'retry: unknown action %', p_action using errcode = '22023';
    end if;
    if p_policy->>'running' is null or p_policy->>'ready' is null
       or p_policy->>'success' is null or p_policy->>'failure' is null
       or p_now is null then
        raise exception 'retry: incomplete policy or clock' using errcode = '22023';
    end if;
    select format_type(atttypid, atttypmod) into key_type
      from pg_attribute where attrelid = p_relation and attname = 'retry_key' and not attisdropped;
    select format_type(atttypid, atttypmod) into status_type
      from pg_attribute where attrelid = p_relation and attname = 'status' and not attisdropped;
    if key_type is null or status_type is null then
        raise exception 'retry: relation % lacks lifecycle columns', p_relation using errcode = '22023';
    end if;
    expected := case p_action
        when 'claim' then array[p_policy->>'ready', p_policy->>'running', p_policy->>'queued']
        when 'requeue' then array[p_policy->>'failure']
        when 'expire' then case when coalesce((p_policy->>'expire_ready')::boolean, false)
                               then array[p_policy->>'running', p_policy->>'ready']
                               else array[p_policy->>'running'] end
        else array[p_policy->>'running'] end;

    -- SKIP LOCKED is essential when claiming/reaping; completion waits for the
    -- row and rechecks status/ownership after any concurrent writer commits.
    execute format(
        'select %s from %s r where retry_key = $1::%s
         and status::text = any($2)
         for update %s',
        projection, p_relation, key_type,
        case when p_action in ('claim', 'expire') then 'skip locked' else '' end)
    into state using p_key, expected;
    if state is null then return; end if;

    if p_action not in ('claim','requeue','expire') and not dbtx.ownership_lock(
        p_relation,p_key,NULL,p_owner,p_token,p_policy->>'running',false,
        coalesce((p_policy->>'check_owner')::boolean,true),
        coalesce((p_policy->>'check_token')::boolean,false)) then return; end if;

    if p_action='renew' then
        if not dbtx.ownership_renew(p_relation,p_key,NULL,p_owner,p_token,p_policy->>'running',false,
            coalesce((p_policy->>'check_owner')::boolean,true),coalesce((p_policy->>'check_token')::boolean,false),
            interval '1 second' * (p_options->>'lease_seconds')::float8,true,p_now) then return; end if;
        execute format('select %s from %s where retry_key=$1::%s',projection,p_relation,key_type)
            into result using p_key;
        return next result;
        return;
    end if;

    next_attempts := (state->>'attempts')::integer;
    max_attempts := coalesce((p_options->>'max_attempts')::integer, (state->>'max_attempts')::integer);
    next_status := state->>'status';
    next_owner := state->>'lease_owner';
    next_error := state->>'last_error';
    next_at := (state->>'retry_at')::timestamptz;
    next_completed := (state->>'completed_at')::timestamptz;

    if p_action = 'claim' then
        if max_attempts is null or next_attempts >= max_attempts
           or (case when next_status = p_policy->>'running'
                    then (state->>'lease_expires_at')::timestamptz
                    else next_at end) > p_now then return; end if;
        if p_owner is null then
            raise exception 'retry: claim requires an owner' using errcode = '22023';
        end if;
        next_status := p_policy->>'running';
        next_owner := p_owner;
        next_attempts := next_attempts + 1;
    elsif p_action = 'nack' then
        if max_attempts is null then
            raise exception 'retry: nack requires an attempt limit' using errcode = '22023';
        end if;
        terminal := coalesce((p_options->>'force')::boolean, false)
                 or (coalesce((p_policy->>'nack_exhausts')::boolean, true) and next_attempts >= max_attempts);
        next_status := case when terminal then p_policy->>'failure' else p_policy->>'ready' end;
        next_owner := null;
        next_error := p_options->>'error';
        if p_options ? 'base_backoff_seconds' then
            delay_seconds := dbtx.retry_delay(next_attempts,
                (p_options->>'base_backoff_seconds')::float8,
                (p_options->>'max_backoff_seconds')::float8);
        else delay_seconds := coalesce((p_options->>'delay_seconds')::float8, 0); end if;
        next_at := case when coalesce((p_policy->>'null_backoff')::boolean, false)
                            and (terminal or delay_seconds <= 0) then null
                        else p_now + interval '1 second' * delay_seconds end;
        if coalesce((p_policy->>'complete_failure')::boolean, false) then
            next_completed := case when terminal then p_now end;
        end if;
    elsif p_action in ('complete', 'fail') then
        next_status := case when p_action = 'complete' then p_policy->>'success' else p_policy->>'failure' end;
        next_owner := null;
        next_error := case when p_action = 'fail' then p_options->>'error'
                          when coalesce((p_policy->>'clear_success_error')::boolean, true) then null
                          else next_error end;
        next_completed := p_now;
        next_at := case p_policy->>'finish_time' when 'clear' then null when 'now' then p_now else next_at end;
    elsif p_action = 'release' then
        next_status := p_policy->>'ready';
        next_owner := null;
        next_attempts := greatest(next_attempts - 1, 0);
        next_at := p_now;
    elsif p_action = 'requeue' then
        next_status := p_policy->>'ready';
        next_owner := null;
        next_attempts := 0;
        next_error := null;
        next_at := p_now;
    elsif p_action = 'expire' then
        if max_attempts is null or next_attempts < max_attempts
           or (state->>'lease_expires_at')::timestamptz > p_now then return; end if;
        next_status := p_policy->>'failure';
        next_owner := null;
        next_error := case when coalesce((p_options->>'keep_error')::boolean, false)
                           then coalesce(next_error, p_options->>'error', 'lease expired on final attempt')
                           else coalesce(p_options->>'error', 'lease expired on final attempt') end;
        if coalesce((p_policy->>'complete_failure')::boolean, false) then next_completed := p_now; end if;
    end if;

    if p_action='claim' then
        if dbtx.ownership_grant(p_relation,p_key,NULL,p_owner,
            interval '1 second' * (p_options->>'lease_seconds')::float8,NULL::regclass,
            coalesce((p_policy->>'increment_token')::boolean,false),true,p_now)=0 then return; end if;
        assignments := 'status=$1::'||status_type||', attempts=$3, updated_at=$7';
    else
        -- Domain constraints couple status/completion and ownership. Clear them
        -- in one UPDATE after the shared ownership guard, never in two writes.
        assignments := 'status=$1::'||status_type||', lease_owner=$2, attempts=$3,last_error=$5,completed_at=$6,updated_at=$7';
        if coalesce((p_policy->>'separate_lease')::boolean,false) then
            assignments := assignments||', retry_at=$4, lease_expires_at=NULL';
        else
            assignments := assignments||', lease_expires_at=$4';
        end if;
    end if;
    execute format('update %s r set %s where retry_key = $8::%s returning %s',
                   p_relation, assignments, key_type, projection)
    into result using next_status, next_owner, next_attempts, next_at,
                      next_error, next_completed, p_now, p_key;
    if result is not null then return next result; end if;
end;
$$;
